// md2a: convert MIT format signal files to AHA DB distribution tape format
// (port of convert/md2a.c, through rust/src/bin/md2a.rs).
//
// The files generated by this program are in the format formerly used for
// distribution of the AHA and MIT-BIH databases on half-inch 9-track digital
// tape. It does *not* generate files in the format currently used for
// distribution of the AHA database on floppy disk; ad2m can perform the
// reverse conversion, however.
//
// This file is part of WFDB-x, an independent reimplementation of the WFDB
// Software Package in Python, C++, MATLAB/Octave, Rust, Julia, R and Kotlin.
//
// It is a Kotlin translation of convert/md2a.c from the WFDB Software Package
// 10.7.0, by George B. Moody. The translation follows the logic and behavior
// of the original program, but it is new code, not the original C code.
//
// Changes from the original: none, apart from the language and the --legacy
// option (as the first argument, it restores the original behavior).
//
// Original C program: convert/md2a.c, WFDB Software Package 10.7.0.
//   Copyright (C) 2001 George B. Moody.
// Kotlin translation and changes: Copyright (C) 2026 Reza Sameni.
//
// This program is free software: you can redistribute it and/or modify it
// under the terms of the GNU General Public License as published by the Free
// Software Foundation, either version 3 of the License, or (at your option)
// any later version. See LICENSE.

package wfdbx.apps

import wfdbx.*
import wfdbx.cstd.*

private const val MD2A_EODF = 0x8000 // AHA data file end-of-data marker (0100000)

private val MD2A_HELP = arrayOf(
    "usage: %s -o AHAFILE -r RECORD [ OPTIONS ... ]\n",
    "where AHAFILE is the name of the AHA-format output signal file,",
    "RECORD is the record name, and OPTIONS may include:",
    " -h         print this usage summary",
    " -n NEWREC  create a header file for the output signal file, so it",
    "             may be read as record NEWREC",
)

private fun md2aHelp(pname: ByteArray) {
    eprintf(MD2A_HELP[0], pname)
    for (k in 1 until MD2A_HELP.size) eprintf("%s\n", MD2A_HELP[k])
}

/** The md2a tool. */
fun Wfdb.md2aMain(argv0: Array<ByteArray>): Int {
    val argv = toolArgv(argv0)
    val argc = argv.size
    val pname = progName(argv[0])
    var nrec: ByteArray? = null
    var ofname: ByteArray? = null
    var record: ByteArray? = null
    val s = Array(WFDB_MAXSIG) { Siginfo() }

    var i = 1
    while (i < argc) {
        val a = argv[i]
        if (a.at(0) == '-'.code) {
            when (a.at(1).toChar()) {
                'h' -> { // help requested
                    md2aHelp(pname)
                    exit(1)
                }
                'n' -> { // new record name follows
                    i++
                    if (i >= argc) {
                        eprintf("%s: new record name must follow -n\n", pname)
                        exit(1)
                    }
                    nrec = argv[i]
                }
                'o' -> { // output file name follows
                    i++
                    if (i >= argc) {
                        eprintf("%s: name of AHA-format output file must follow -o\n", pname)
                        exit(1)
                    }
                    ofname = argv[i]
                }
                'r' -> {
                    i++
                    if (i >= argc) {
                        eprintf("%s: record name must follow -r\n", pname)
                        exit(1)
                    }
                    record = argv[i]
                }
                else -> {
                    eprintf("%s: unrecognized option %s\n", pname, a)
                    exit(1)
                }
            }
        } else {
            eprintf("%s: unrecognized argument %s\n", pname, a)
            exit(1)
        }
        i++
    }
    if (ofname == null || record == null) {
        md2aHelp(pname)
        exit(1)
    }

    // Give up unless at least one input signal is readable.
    val nsig = isigopen(record, s, WFDB_MAXSIG)
    if (nsig < 1) exit(2)

    // Check that the new record name is legal before proceeding. Note that
    // this step creates a header file in the current directory which is
    // overwritten below, after the processing is completed.
    if (nrec != null && newheader(nrec) < 0) exit(3)

    // Set the output signal specifications.
    for (k in 0 until nsig) {
        s[k].fname = cstr(ofname)
        s[k].desc = ByteArray(0)
        s[k].group = 0
        s[k].fmt = 16
    }

    // Give up if the output cannot be written.
    if (osigfopen(s, nsig) < nsig) exit(4)

    // Copy the input to the output. Reformatting is handled by putvec().
    // x has one element per output sample of a frame (at least
    // WFDB_MAXSIG); getvec sets the first nsig, the others stay zero. (In
    // C, x is an uninitialized array of WFDB_MAXSIG; see "Undefined
    // behaviors" in docs/KNOWN_C_BEHAVIORS.md.)
    var nout = 0
    for (k in 0 until nsig) nout += maxOf(s[k].spf, 1)
    val x = IntArray(maxOf(nout, WFDB_MAXSIG))
    while (getvec(x) == nsig && putvec(x) == nsig) {
        // copy
    }

    // Write the new header file if requested.
    if (nrec != null) newheader(nrec)

    // Write the end-of-data marker.
    for (k in 0 until nsig) x[k] = MD2A_EODF
    putvec(x)

    // Clean up.
    wfdbquit()
    exit(0)
}
